    12.1973
  ],
  "indicator_readings": [
    {
      "indicator": "Preço (fechamento)",
      "reading": "12.51 (2024-08-01)",
      "interpretation": "Fechamento acima das médias móveis (MM20/MM50/MM200) e acima da banda superior de Bollinger — breakout de alta."
    },
    {
      "indicator": "MM20",
      "reading": "11.4805",
      "interpretation": "Curto prazo altista; MM20 acima de MM50 e MM200; atua como suporte dinâmico."
    },
    {
      "indicator": "MM50",
      "reading": "11.4202",
      "interpretation": "Médio prazo em alta; suporte de referência."
    },
    {
      "indicator": "MM200",
      "reading": "10.1616",
      "interpretation": "Tendência de longo prazo positiva; suporte estrutural relevante em eventuais correções."
    },
    {
      "indicator": "EMA9",
      "reading": "11.8004",
      "interpretation": "EMA9 acima da EMA21 e preço acima da EMA9 — suporte de curto prazo; confirma impulso comprador."
    },
    {
      "indicator": "EMA21",
      "reading": "11.5650",
      "interpretation": "EMA21 alinhada com tendência de alta; confirmatória do movimento curto/médio prazo."
    },
    {
