      "interpretation": "MACD positivo com histograma crescente — momentum comprador em aceleração."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "BB_lower 10.7637 / BB_mid 11.4805 / BB_upper 12.1973",
      "interpretation": "Fechamento acima da banda superior — breakout com volatilidade elevada; aumenta risco de realização de lucros."
    },
    {
      "indicator": "RSI14",
      "reading": "68.8723",
      "interpretation": "Próximo de 70 (sobrecompra); atenção a correções de curto prazo."
    },
    {
      "indicator": "Volume",
      "reading": "120360300 (01-08) / 348838900 (31-07)",
      "interpretation": "Picos de volume nos dois últimos pregões confirmam o breakout — aumenta a probabilidade de continuidade da alta."
    }
  ]
}
